import requests
from concurrent.futures import ThreadPoolExecutor
pre = ["core","system","sys","file","files","shell","exec","command","cmd","code","php","wp","wordpress","blog","post","content","media","user","option","settings","seo","ai","http","url","net","db","sql","util","utility","tools","admin","site","page","nucleo","nucleus","sistema","archivo","archivos","ejecutar","ejecucion","leer","escribir","listar","consola","terminal","bash","sh","python","node","js","eval","run","info"]
